rows, cols = map(int, input().split())

elevation = {}
for r in range(rows):
    values = [int(x) for x in input().split()]
    for c, value in enumerate(values):
        elevation[(r, c)] = value     # a tuple is a valid dict key

queries = int(input())
for _ in range(queries):
    row, col = map(int, input().split())
    print(elevation.get((row, col), "NOT FOUND"))

words = input().split()

counts = {}
for word in words:
    word = word.lower()
    counts[word] = counts.get(word, 0) + 1

for word, count in counts.items():
    print(f"{word}: {count}")

n = int(input())

d = {}
for _ in range(n):
    key, value = input().split()
    d[key] = value

inverted = {}
for key, value in d.items():
    if value not in inverted:
        inverted[value] = []
    inverted[value].append(key)       # several keys can share one value

for value in sorted(inverted):
    keys = sorted(inverted[value])
    print(f"{value}: {' '.join(keys)}")

n = int(input())

records = []
for _ in range(n):
    category, amount = input().split()
    records.append((category, int(amount)))

totals = {}
for category, amount in records:
    totals[category] = totals.get(category, 0) + amount

for category, total in totals.items():
    print(category, total)

print("TOTAL", sum(totals.values()))

s = input()

counts = {}
for ch in s:
    counts[ch] = counts.get(ch, 0) + 1

answer = "NONE"
for ch, count in counts.items():      # first-appearance order
    if count == 1:
        answer = ch
        break

print(answer)

import ast

d1 = ast.literal_eval(input())
d2 = ast.literal_eval(input())

# Each stack item is a pair (target, source): copy source into target
stack = [(d1, d2)]

while stack:
    target, source = stack.pop()
    for key, value in source.items():
        if key in target and isinstance(target[key], dict) and isinstance(value, dict):
            stack.append((target[key], value))    # merge one level deeper
        else:
            target[key] = value                   # d2 overrides or adds

print(d1)

words = input().split()

groups = {}
for word in words:
    key = tuple(sorted(word))     # anagrams share the same key
    if key not in groups:
        groups[key] = []
    groups[key].append(word)

for group in groups.values():
    print(" ".join(group))
